import{_ as e,o as a,c as s,O as n}from"./chunks/framework.2c2d5a61.js";const b=JSON.parse('{"title":"Kafka 深入","description":"","frontmatter":{},"headers":[],"relativePath":"backend/Java/Kafka深入.md","filePath":"backend/Java/Kafka深入.md","lastUpdated":1793005160000}'),r={name:"backend/Java/Kafka深入.md"};function o(d,t,l,c,i,p){return a(),s("div",null,t[0]||(t[0]=[n(`<h1 id="kafka-深入" tabindex="-1">Kafka 深入 <a class="header-anchor" href="#kafka-深入" aria-label="Permalink to &quot;Kafka 深入&quot;">​</a></h1><blockquote><p>相关笔记：<a href="./消息队列">消息队列</a>（RabbitMQ / Kafka 基础与选型）、<a href="./定时任务调度">定时任务调度</a>（延迟消息对比）</p></blockquote><blockquote><p><a href="./消息队列">消息队列</a> 那篇讲的是「MQ 怎么用、怎么选」；这篇往下挖一层：<strong>Kafka 的存储、副本、ISR、再均衡、Exactly-Once</strong>。</p></blockquote><h2 id="_1-架构与核心概念" tabindex="-1">1. 架构与核心概念 <a class="header-anchor" href="#_1-架构与核心概念" aria-label="Permalink to &quot;1. 架构与核心概念&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">Producer ──► Topic（逻辑概念）</span></span>
<span class="line"><span style="color:#e1e4e8;">              ├── Partition 0  (Leader: Broker1, Follower: Broker2/3)</span></span>
<span class="line"><span style="color:#e1e4e8;">              ├── Partition 1  (Leader: Broker2, Follower: Broker1/3)</span></span>
<span class="line"><span style="color:#e1e4e8;">              └── Partition 2  (Leader: Broker3, Follower: Broker1/2)</span></span>
<span class="line"><span style="color:#e1e4e8;">Consumer Group ── 每个分片只会被组内一个消费者消费</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">Producer ──► Topic（逻辑概念）</span></span>
<span class="line"><span style="color:#24292e;">              ├── Partition 0  (Leader: Broker1, Follower: Broker2/3)</span></span>
<span class="line"><span style="color:#24292e;">              ├── Partition 1  (Leader: Broker2, Follower: Broker1/3)</span></span>
<span class="line"><span style="color:#24292e;">              └── Partition 2  (Leader: Broker3, Follower: Broker1/2)</span></span>
<span class="line"><span style="color:#24292e;">Consumer Group ── 每个分片只会被组内一个消费者消费</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><table><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td><strong>Broker</strong></td><td>一个 Kafka 节点</td></tr><tr><td><strong>Topic</strong></td><td>逻辑主题，实际由多个 Partition 组成</td></tr><tr><td><strong>Partition</strong></td><td><strong>并行与顺序的最小单位</strong>，一个分区内严格有序</td></tr><tr><td><strong>Replica</strong></td><td>分区的副本，分 Leader / Follower</td></tr><tr><td><strong>ISR</strong></td><td>In-Sync Replicas，与 Leader 保持同步的副本集合（含 Leader）</td></tr><tr><td><strong>Consumer Group</strong></td><td>组内互斥消费，组间广播</td></tr><tr><td><strong>Offset</strong></td><td>分区内的消息位移，消费者提交的是「我消费到哪了」</td></tr></tbody></table><p><strong>为什么吞吐高</strong>：分区并行 + 顺序写盘 + 页缓存 + 批量 + 零拷贝 + 压缩。这几个词能串起来讲，就够面试用了。</p><h2 id="_2-存储设计" tabindex="-1">2. 存储设计 <a class="header-anchor" href="#_2-存储设计" aria-label="Permalink to &quot;2. 存储设计&quot;">​</a></h2><h3 id="_2-1-分段日志" tabindex="-1">2.1 分段日志 <a class="header-anchor" href="#_2-1-分段日志" aria-label="Permalink to &quot;2.1 分段日志&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">topic-order-partition-0/</span></span>
<span class="line"><span style="color:#e1e4e8;">├── 00000000000000000000.log      ← 消息本体</span></span>
<span class="line"><span style="color:#e1e4e8;">├── 00000000000000000000.index    ← 稀疏索引（offset → 物理位置）</span></span>
<span class="line"><span style="color:#e1e4e8;">├── 00000000000000000000.timeindex</span></span>
<span class="line"><span style="color:#e1e4e8;">└── 00000000000000032580.log      ← 满了 1GB 就滚动</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">topic-order-partition-0/</span></span>
<span class="line"><span style="color:#24292e;">├── 00000000000000000000.log      ← 消息本体</span></span>
<span class="line"><span style="color:#24292e;">├── 00000000000000000000.index    ← 稀疏索引（offset → 物理位置）</span></span>
<span class="line"><span style="color:#24292e;">├── 00000000000000000000.timeindex</span></span>
<span class="line"><span style="color:#24292e;">└── 00000000000000032580.log      ← 满了 1GB 就滚动</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ul><li>每个 segment 默认 <strong>1GB</strong>（<code>log.segment.bytes</code>）；</li><li><strong>稀疏索引</strong>：不是每条都建索引，而是每 4KB 建一条（<code>log.index.interval.bytes</code>），所以是「先二分定位到接近的位置，再顺序扫」；</li><li>查找消息 = 二分查 <code>.index</code> 找 segment 内的近似位置 → 从 <code>.log</code> 顺序扫到目标 offset。</li></ul><h3 id="_2-2-顺序写-页缓存" tabindex="-1">2.2 顺序写 + 页缓存 <a class="header-anchor" href="#_2-2-顺序写-页缓存" aria-label="Permalink to &quot;2.2 顺序写 + 页缓存&quot;">​</a></h3><p>Kafka 只做<strong>追加写</strong>，不做随机写 —— 顺序写盘能到几百 MB/s，随机写只有几 MB/s。这是它敢用磁盘扛百万 TPS 的根本原因。</p><p>读的时候优先命中 <strong>OS 页缓存</strong>（Kafka 自己不维护缓存，交给操作系统），所以「消费者追得上生产者」时几乎不读盘。</p><h3 id="_2-3-零拷贝" tabindex="-1">2.3 零拷贝 <a class="header-anchor" href="#_2-3-零拷贝" aria-label="Permalink to &quot;2.3 零拷贝&quot;">​</a></h3><p>消费者拉数据时走 <code>sendfile</code>：数据从页缓存直接进 socket，<strong>不经过 JVM 堆</strong>，省掉两次拷贝。配合批量拉取，这是高吞吐的另一半原因。</p><blockquote><p>详见 <a href="./07-Java网络编程与NIO">07 Java 网络编程与 NIO</a> 第 6 节。</p></blockquote><h2 id="_3-生产者" tabindex="-1">3. 生产者 <a class="header-anchor" href="#_3-生产者" aria-label="Permalink to &quot;3. 生产者&quot;">​</a></h2><h3 id="_3-1-发送流程" tabindex="-1">3.1 发送流程 <a class="header-anchor" href="#_3-1-发送流程" aria-label="Permalink to &quot;3.1 发送流程&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">send() → 拦截器 → 序列化 → 分区器 → 累加器（RecordAccumulator，按分区攒批）</span></span>
<span class="line"><span style="color:#e1e4e8;">                                              │</span></span>
<span class="line"><span style="color:#e1e4e8;">                        Sender 线程按 batch.size / linger.ms 发送</span></span>
<span class="line"><span style="color:#e1e4e8;">                                              │</span></span>
<span class="line"><span style="color:#e1e4e8;">                                     Broker 返回 ack / 错误重试</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">send() → 拦截器 → 序列化 → 分区器 → 累加器（RecordAccumulator，按分区攒批）</span></span>
<span class="line"><span style="color:#24292e;">                                              │</span></span>
<span class="line"><span style="color:#24292e;">                        Sender 线程按 batch.size / linger.ms 发送</span></span>
<span class="line"><span style="color:#24292e;">                                              │</span></span>
<span class="line"><span style="color:#24292e;">                                     Broker 返回 ack / 错误重试</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>关键配置：</p><table><thead><tr><th>参数</th><th>作用</th><th>建议</th></tr></thead><tbody><tr><td><code>acks</code></td><td>0 / 1 / all(-1)</td><td>金融级用 <code>all</code></td></tr><tr><td><code>retries</code></td><td>重试次数</td><td>配合幂等，设大</td></tr><tr><td><code>enable.idempotence</code></td><td>幂等生产者</td><td><strong>强烈建议 true</strong></td></tr><tr><td><code>batch.size</code></td><td>单批字节数</td><td>默认 16KB，吞吐优先可到 64~128KB</td></tr><tr><td><code>linger.ms</code></td><td>攒批等待</td><td>默认 0，吞吐优先设 5~20ms</td></tr><tr><td><code>compression.type</code></td><td>压缩算法</td><td><code>lz4</code>（快）或 <code>zstd</code>（省）</td></tr><tr><td><code>max.in.flight.requests.per.connection</code></td><td>未确认请求数</td><td>要顺序 + 重试时设 1，或开幂等</td></tr></tbody></table><h3 id="_3-2-分区器" tabindex="-1">3.2 分区器 <a class="header-anchor" href="#_3-2-分区器" aria-label="Permalink to &quot;3.2 分区器&quot;">​</a></h3><ul><li>指定 key → <code>hash(key) % 分区数</code>，<strong>同 key 必进同分区</strong>（这是「局部有序」的实现方式）；</li><li>无 key → 2.4 之前是轮询，之后是<strong>粘性分区</strong>（Sticky：一批发完再换分区，减少小批次、提升吞吐）。</li></ul><h3 id="_3-3-幂等与事务" tabindex="-1">3.3 幂等与事务 <a class="header-anchor" href="#_3-3-幂等与事务" aria-label="Permalink to &quot;3.3 幂等与事务&quot;">​</a></h3><ul><li><strong>幂等生产者</strong>：给每个生产者分配 PID，每条消息带 <code>&lt;PID, 分区, 序列号&gt;</code>，Broker 侧去重。解决「重试导致的重复」。</li><li><strong>事务</strong>：<code>transactional.id</code> + 两阶段提交，解决「跨分区原子写」（读-处理-写场景，配合 <code>read_committed</code> 消费）。</li></ul><blockquote><p>注意：幂等只保证<strong>单个生产者会话内、单分区</strong>不重复；跨会话、跨分区要靠事务。</p></blockquote><h2 id="_4-消费者" tabindex="-1">4. 消费者 <a class="header-anchor" href="#_4-消费者" aria-label="Permalink to &quot;4. 消费者&quot;">​</a></h2><h3 id="_4-1-消费者组与再均衡" tabindex="-1">4.1 消费者组与再均衡 <a class="header-anchor" href="#_4-1-消费者组与再均衡" aria-label="Permalink to &quot;4.1 消费者组与再均衡&quot;">​</a></h3><p>一个分区只能被组内<strong>一个</strong>消费者消费。消费者增减、分区数变化、订阅关系变化都会触发 <strong>Rebalance</strong>。</p><table><thead><tr><th>分配策略</th><th>特点</th></tr></thead><tbody><tr><td>Range</td><td>按主题范围分，分区数少时容易不均</td></tr><tr><td>RoundRobin</td><td>跨主题轮询，均匀</td></tr><tr><td>Sticky</td><td>尽量保留上次分配，减少抖动</td></tr><tr><td><strong>CooperativeSticky</strong></td><td><strong>增量再均衡</strong>，不用全局停顿（推荐）</td></tr></tbody></table><p><strong>再均衡的代价</strong>：整个过程 Stop-The-World（Eager 协议），期间不消费。所以：</p><ul><li>用 <code>CooperativeSticky</code> 做增量式；</li><li>配 <code>group.instance.id</code>（静态成员），重启不触发再均衡；</li><li>会话超时、心跳参数要调：<code>session.timeout.ms</code>、<code>heartbeat.interval.ms</code>、<code>max.poll.interval.ms</code>（<strong>处理太慢被踢出组</strong>，这是最常见的线上事故）。</li></ul><h3 id="_4-2-位移提交" tabindex="-1">4.2 位移提交 <a class="header-anchor" href="#_4-2-位移提交" aria-label="Permalink to &quot;4.2 位移提交&quot;">​</a></h3><table><thead><tr><th>方式</th><th>风险</th></tr></thead><tbody><tr><td>自动提交 <code>enable.auto.commit=true</code></td><td>可能在处理前就提交了 → <strong>丢消息</strong></td></tr><tr><td>手动同步 <code>commitSync()</code></td><td>安全但阻塞、慢</td></tr><tr><td>手动异步 <code>commitAsync()</code></td><td>快，但失败不回滚，重试可能乱序</td></tr></tbody></table><p><strong>标准写法</strong>：正常用 <code>commitAsync</code>，<code>finally</code> 或关闭时用 <code>commitSync</code> 兜底。并且<strong>先处理再提交</strong>。</p><h2 id="_5-hw-leo-isr-一致性核心" tabindex="-1">5. HW / LEO / ISR：一致性核心 <a class="header-anchor" href="#_5-hw-leo-isr-一致性核心" aria-label="Permalink to &quot;5. HW / LEO / ISR：一致性核心&quot;">​</a></h2><table><thead><tr><th>概念</th><th>含义</th></tr></thead><tbody><tr><td><strong>LEO</strong>（Log End Offset）</td><td>每个副本最后一条消息的下一个位置</td></tr><tr><td><strong>HW</strong>（High Watermark）</td><td><strong>ISR 中最小的 LEO</strong>，消费者只能看到 HW 之前的消息</td></tr><tr><td><strong>ISR</strong></td><td>与 Leader 保持同步的副本（<code>replica.lag.time.max.ms</code> 内追得上）</td></tr></tbody></table><p><strong>为什么要 HW</strong>：如果允许消费者读到还没同步到所有 ISR 的消息，一旦 Leader 挂了、由落后的副本接任，这条消息就「消失」了 —— 消费过的东西又不存在，等于数据丢失。所以<strong>只暴露 HW 之前的</strong>。</p><p><strong>Leader 选举</strong>：</p><ul><li>默认只从 ISR 里选（<code>unclean.leader.election.enable=false</code>）；</li><li>如果 ISR 全挂，宁可不可用也不选落后副本 —— 保一致性（CP）。</li><li>打开 <code>unclean.leader.election</code> 就变成可用性优先（AP），可能丢数据。</li></ul><p><strong>必须一起配的两个参数</strong>：</p><div class="language-properties vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#F97583;">acks</span><span style="color:#E1E4E8;">=all                      </span><span style="color:#6A737D;"># 生产者等所有 ISR 确认</span></span>
<span class="line"><span style="color:#F97583;">min.insync.replicas</span><span style="color:#E1E4E8;">=2         </span><span style="color:#6A737D;"># 至少 2 个副本确认，否则报错而不是静默降级</span></span>
<span class="line"><span style="color:#F97583;">replication.factor</span><span style="color:#E1E4E8;">=3          </span><span style="color:#6A737D;"># 副本数 3，容忍挂 1</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#D73A49;">acks</span><span style="color:#24292E;">=all                      </span><span style="color:#6A737D;"># 生产者等所有 ISR 确认</span></span>
<span class="line"><span style="color:#D73A49;">min.insync.replicas</span><span style="color:#24292E;">=2         </span><span style="color:#6A737D;"># 至少 2 个副本确认，否则报错而不是静默降级</span></span>
<span class="line"><span style="color:#D73A49;">replication.factor</span><span style="color:#24292E;">=3          </span><span style="color:#6A737D;"># 副本数 3，容忍挂 1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><blockquote><p>面试口径：<code>acks=all</code> 不等于「万无一失」，还要 <code>min.insync.replicas &gt;= 2</code> 且副本数 &gt;= 3。三者缺一，都可能丢消息。</p></blockquote><h2 id="_6-三个经典问题-不丢、不重、不乱序" tabindex="-1">6. 三个经典问题：不丢、不重、不乱序 <a class="header-anchor" href="#_6-三个经典问题-不丢、不重、不乱序" aria-label="Permalink to &quot;6. 三个经典问题：不丢、不重、不乱序&quot;">​</a></h2><h3 id="_6-1-不丢消息" tabindex="-1">6.1 不丢消息 <a class="header-anchor" href="#_6-1-不丢消息" aria-label="Permalink to &quot;6.1 不丢消息&quot;">​</a></h3><table><thead><tr><th>环节</th><th>措施</th></tr></thead><tbody><tr><td>生产端</td><td><code>acks=all</code> + <code>retries</code> 大 + 幂等开启</td></tr><tr><td>Broker</td><td>副本数 3 + <code>min.insync.replicas=2</code> + <code>unclean.leader.election=false</code></td></tr><tr><td>消费端</td><td><strong>处理成功后再提交位移</strong>，别用自动提交</td></tr><tr><td>跨系统</td><td>本地消息表 / 事务消息（RocketMQ）做最终一致</td></tr></tbody></table><h3 id="_6-2-不重复消费" tabindex="-1">6.2 不重复消费 <a class="header-anchor" href="#_6-2-不重复消费" aria-label="Permalink to &quot;6.2 不重复消费&quot;">​</a></h3><p>Kafka 只保证「至少一次」（at-least-once），<strong>重复必然发生</strong>，所以只能<strong>消费端幂等</strong>：</p><ul><li>唯一键 + 去重表（<code>insert ignore</code> 或先查后插 + 唯一索引）；</li><li>Redis <code>SETNX</code> 标记已处理的消息 id；</li><li>业务状态机：只允许「待支付 → 已支付」这种单向流转，重复执行无副作用。</li></ul><h3 id="_6-3-不乱序" tabindex="-1">6.3 不乱序 <a class="header-anchor" href="#_6-3-不乱序" aria-label="Permalink to &quot;6.3 不乱序&quot;">​</a></h3><ul><li><strong>单分区内天然有序</strong>，跨分区不保证；</li><li>要顺序 → <strong>同 key 打同分区</strong>（订单号做 key）；</li><li>生产端重试会乱序 → 开幂等（<code>max.in.flight &lt;= 5</code>）或设 <code>max.in.flight=1</code>；</li><li>消费端多线程处理会乱序 → 按 key 哈希到固定线程，或用「单分区单线程」。</li></ul><h2 id="_7-高性能原因-面试高频总结" tabindex="-1">7. 高性能原因（面试高频总结） <a class="header-anchor" href="#_7-高性能原因-面试高频总结" aria-label="Permalink to &quot;7. 高性能原因（面试高频总结）&quot;">​</a></h2><ol><li><strong>分区并行</strong>：横向扩展，一个 topic 多个分区同时读写。</li><li><strong>顺序写</strong>：只追加，磁盘顺序写接近内存速度。</li><li><strong>页缓存</strong>：读命中 OS 缓存，不自己管内存。</li><li><strong>零拷贝</strong>：<code>sendfile</code> 让数据不进 JVM 堆。</li><li><strong>批量 + 压缩</strong>：<code>batch.size</code> + <code>linger.ms</code> + lz4/zstd。</li><li><strong>稀疏索引</strong>：索引小，内存占用低，二分 + 顺序扫很快。</li></ol><h2 id="_8-常见运维与调优" tabindex="-1">8. 常见运维与调优 <a class="header-anchor" href="#_8-常见运维与调优" aria-label="Permalink to &quot;8. 常见运维与调优&quot;">​</a></h2><table><thead><tr><th>场景</th><th>处理</th></tr></thead><tbody><tr><td>消息积压</td><td>加消费者（≤ 分区数）、扩分区、提升单条处理速度、临时降级</td></tr><tr><td>分区热点</td><td>检查 key 分布（某个 key 太热），加随机后缀打散</td></tr><tr><td>磁盘满</td><td>调 <code>log.retention.hours/bytes</code>、开 <code>log.cleanup.policy=delete/compact</code></td></tr><tr><td>重复消费暴增</td><td>查是否有频繁 Rebalance（<code>max.poll.interval.ms</code> 太小 / 处理太慢）</td></tr><tr><td>延迟高</td><td>查 <code>linger.ms</code>、<code>acks</code>、压缩、网络、ISR 抖动</td></tr><tr><td>消费 lag 监控</td><td><code>kafka-consumer-groups.sh --describe</code>，或 Burrow / KM（Kafka Exporter）</td></tr></tbody></table><h2 id="_9-与其他-mq-对比" tabindex="-1">9. 与其他 MQ 对比 <a class="header-anchor" href="#_9-与其他-mq-对比" aria-label="Permalink to &quot;9. 与其他 MQ 对比&quot;">​</a></h2><table><thead><tr><th>维度</th><th>Kafka</th><th>RocketMQ</th><th>RabbitMQ</th><th>Pulsar</th></tr></thead><tbody><tr><td>定位</td><td>流平台、日志管道</td><td>业务消息、事务消息</td><td>灵活路由、低延迟</td><td>云原生、存算分离</td></tr><tr><td>吞吐</td><td>极高（百万级）</td><td>高（十万级）</td><td>中（万级）</td><td>高</td></tr><tr><td>延迟</td><td>ms 级</td><td>ms 级</td><td><strong>μs~ms</strong></td><td>ms 级</td></tr><tr><td>顺序</td><td>分区内有序</td><td>队列内有序</td><td>队列内有序</td><td>分区内有序</td></tr><tr><td>事务消息</td><td>有（较复杂）</td><td><strong>原生支持</strong></td><td>不支持</td><td>有</td></tr><tr><td>延迟消息</td><td>不支持（要靠外部）</td><td>支持（等级延迟）</td><td>插件支持</td><td>支持</td></tr><tr><td>运维</td><td>中等</td><td>中等</td><td>简单</td><td>复杂</td></tr></tbody></table><blockquote><p>选型口径：日志/埋点/流处理选 Kafka；业务消息要事务、延迟、重试选 RocketMQ；路由复杂、量不大选 RabbitMQ。</p></blockquote><h2 id="_10-速查表" tabindex="-1">10. 速查表 <a class="header-anchor" href="#_10-速查表" aria-label="Permalink to &quot;10. 速查表&quot;">​</a></h2><table><thead><tr><th>问题</th><th>一句话</th></tr></thead><tbody><tr><td>为什么快</td><td>分区并行 + 顺序写 + 页缓存 + 零拷贝 + 批量压缩</td></tr><tr><td>分区与顺序</td><td>分区内有序，跨分区无序；同 key 进同分区</td></tr><tr><td>HW 是什么</td><td>ISR 中最小的 LEO，消费者只能读到 HW 之前</td></tr><tr><td>ISR 作用</td><td>只从同步副本里选 Leader，避免丢数据</td></tr><tr><td>acks 三种</td><td>0 不等、1 等 Leader、all 等所有 ISR</td></tr><tr><td>怎么不丢</td><td>acks=all + 副本3 + min.insync=2 + 手动提交</td></tr><tr><td>怎么不重</td><td>消费端幂等（唯一键/去重表/状态机）</td></tr><tr><td>怎么不乱序</td><td>同 key 同分区 + 幂等生产者 + 单线程消费</td></tr><tr><td>再均衡代价</td><td>STW 不消费；用 CooperativeSticky + 静态成员</td></tr><tr><td>幂等 vs 事务</td><td>幂等管单会话单分区去重，事务管跨分区原子</td></tr></tbody></table>`,61)]))}const g=e(r,[["render",o]]);export{b as __pageData,g as default};
